import React, { useState } from "react";
import Login from "./components/login";
import IncomeCategory from "./components/IncomeCategory";
import SpendingPriority from "./components/SpendingPriority";
import BudgetLimits from "./components/BudgetLimits";
import Dashboard from "./components/Dashboard";
import Preview from "./components/Preview";
import Questionnaire from "./components/Questionnaire";

function App() {
  const [step, setStep] = useState("login");

  const [data, setData] = useState({
    income: "",
    questionnaire: {},
    categories: [],
    priorities: [],
    limits: {}
  });

  return (
    <>
      {step === "login" && (
        <Login onLogin={() => setStep("income")} />
      )}

      {step === "income" && (
        <IncomeCategory
          onNext={(val) => {
            setData(prev => ({ ...prev, income: val }));
            setStep("questionnaire");
          }}
        />
      )}

      {step === "questionnaire" && (
        <Questionnaire
          onNext={(answers) => {
            setData(prev => ({ ...prev, questionnaire: answers }));
            setStep("priority");
          }}
          onBack={() => setStep("income")}
        />
      )}

      {step === "priority" && (
        <SpendingPriority
          onNext={(priorities) => {
            setData(prev => ({
              ...prev,
              priorities,
              categories: priorities // ✅ IMPORTANT FIX
            }));
            setStep("budget");
          }}
          onBack={() => setStep("questionnaire")}
        />
      )}

      {step === "budget" && (
        <BudgetLimits
          selectedCategories={data.categories}
          onNext={(limits) => {
            setData(prev => ({ ...prev, limits }));
            setStep("preview");
          }}
          onBack={() => setStep("priority")}
        />
      )}

      {step === "preview" && (
  <Preview
    data={data}
    updateData={setData}   // ✅ THIS WAS MISSING
    onEdit={() => setStep("income")}
    onConfirm={() => setStep("dashboard")}
  />
)}

      {step === "dashboard" && (
        <Dashboard />
      )}
    </>
  );
}

export default App;
